using System.Collections;
using System.Diagnostics;
using System.Reflection;
using System.Security.Cryptography;
using System.Text.Json;
using HarmonyLib;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Models;
using STS2RitsuLib.Cards.FreePlay;
using STS2RitsuLib.Combat.SecondaryResources;

namespace CombatSolver;

internal sealed partial class UnattendedTestRunner
{
    private sealed record TaskFreeCard(string Location, string CardId, bool HasBinding,
        int Next, int ThisTurn, int RestOfTurn, bool HasCombatReference,
        bool CostContainer, int CostResources, int CostLayers, int CostCallbacks,
        bool UseContainer, int UseResources, int UseLayers, int UseCallbacks);

    private static FieldInfo TaskFreeField(Type type, string name) => type.GetField(name,
        BindingFlags.Static | BindingFlags.Instance | BindingFlags.NonPublic | BindingFlags.Public)!;

    private static object TaskFreeAttachedStore(string name)
        => TaskFreeField(typeof(FreePlayBindingRegistry), name).GetValue(null)!;

    private static object? TaskReadExistingFreeBinding(CardModel card)
    {
        object store = TaskFreeAttachedStore("CardStates");
        object?[] args = [card, null];
        bool exists = (bool)store.GetType().GetMethod("TryGetValue")!.Invoke(store, args)!;
        return exists ? args[1] : null;
    }

    private static int TaskFreeInt(object? state, string name)
        => state is null ? 0 : (int)state.GetType().GetProperty(name)!.GetValue(state)!;

    private static (int Resources, int Layers, int Callbacks) TaskFreeLayerState(object? container, string name)
    {
        if (container is null) return (0, 0, 0);
        IDictionary resources = (IDictionary)TaskFreeField(container.GetType(), name).GetValue(container)!;
        int layers = resources.Values.Cast<IList>().Sum(list => list.Count);
        int callbacks = ((Delegate?)TaskFreeField(container.GetType(), "Changed").GetValue(container))
            ?.GetInvocationList().Length ?? 0;
        return (resources.Count, layers, callbacks);
    }

    private static TaskFreeCard TaskReadFreeCard(CardModel card, string location)
    {
        object? binding = TaskReadExistingFreeBinding(card);
        bool costContainer = card.TryGetSecondaryCosts(out SecondaryResourceCostSet costs);
        bool useContainer = card.TryGetSecondaryResourceUses(out SecondaryResourcePlayUseSet uses);
        var cost = TaskFreeLayerState(costContainer ? costs : null, "_costs");
        var use = TaskFreeLayerState(useContainer ? uses : null, "_uses");
        return new(location, card.Id.Entry, binding is not null,
            TaskFreeInt(binding, "BaseCostsFreeNextPlayCharges"),
            TaskFreeInt(binding, "BaseCostsFreeThisTurnCharges"),
            TaskFreeInt(binding, "BaseCostsFreeForRestOfTurnCharges"),
            binding?.GetType().GetProperty("BaseCostsFreeThisCombatState")!.GetValue(binding) is not null,
            costContainer, cost.Resources, cost.Layers, cost.Callbacks,
            useContainer, use.Resources, use.Layers, use.Callbacks);
    }

    private static bool TaskFreeCardHasNoMechanism(TaskFreeCard card)
        => card.Next == 0 && card.ThisTurn == 0 && card.RestOfTurn == 0 && !card.HasCombatReference
            && card.CostLayers == 0 && card.UseLayers == 0 && card.CostCallbacks == 0 && card.UseCallbacks == 0;

    private static KeyValuePair<string, Func<CardPlay, bool>>[] TaskReadFreeDetectors()
    {
        var gate = (System.Threading.Lock)TaskFreeField(typeof(FreePlayBindingRegistry), "Gate").GetValue(null)!;
        using (gate.EnterScope())
            return ((Dictionary<string, Func<CardPlay, bool>>)TaskFreeField(typeof(FreePlayBindingRegistry),
                "RegisteredDetectors").GetValue(null)!).OrderBy(pair => pair.Key, StringComparer.Ordinal).ToArray();
    }

    private static object[] TaskReadFreePlayEntries(HashSet<CardModel> rootCards)
    {
        object store = TaskFreeAttachedStore("PlayStates");
        IEnumerable table = (IEnumerable)TaskFreeField(store.GetType(), "_table").GetValue(store)!;
        List<object> rows = [];
        foreach (object entry in table)
        {
            var play = (CardPlay)entry.GetType().GetProperty("Key")!.GetValue(entry)!;
            object box = entry.GetType().GetProperty("Value")!.GetValue(entry)!;
            object state = box.GetType().GetProperty("Value")!.GetValue(box)!;
            rows.Add(new { cardId = play.Card.Id.Entry, belongsToRootCard = rootCards.Contains(play.Card),
                isResolved = (bool)state.GetType().GetProperty("IsResolved")!.GetValue(state)!,
                resolution = state.GetType().GetProperty("Resolution")!.GetValue(state) });
        }
        return rows.ToArray();
    }

    private Task RunTaskFreeRootAsync(CombatState live, Player player)
    {
        CombatRootSnapshot root = CombatRootSnapshot.Capture(live);
        CombatPredictionSimulator parent = root.ForkSimulator();
        string ParentState() => ContinuationStamp.CapturePredicted(player, parent,
            ((SimulatedCombatState)parent.State.CombatState).GetPlayerTurnNumber(player), root.Forecast,
            root.StartTurnNumber).StateText + "\nHISTORY=" + CardContinuationContractHistoryText(parent);
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText, parentBefore = ParentState();
        var cards = new HashSet<CardModel>(ReferenceEqualityComparer.Instance);
        foreach (Player owner in live.Players)
            foreach (CardModel card in owner.Deck.Cards.Concat(owner.PlayerCombatState!.AllCards)) cards.Add(card);
        foreach (CardModel card in ((IEnumerable)TaskFreeField(typeof(CombatState), "_allCards")
                     .GetValue(live)!).Cast<CardModel>()) cards.Add(card);
        foreach (var returning in ((SimulatedCombatState)parent.State.CombatState).PendingReturningCards)
            cards.Add(returning.Preview);
        CardModel[] orderedCards = cards.ToArray();
        Stopwatch timer = Stopwatch.StartNew();
        TaskFreeCard[] before = orderedCards.Select((card, index) => TaskReadFreeCard(card, "root/" + index)).ToArray();
        TaskFreeCard[] repeated = orderedCards.Select((card, index) => TaskReadFreeCard(card, "root/" + index)).ToArray();
        var detectors = TaskReadFreeDetectors();
        var definitions = ModSecondaryResourceRegistry.GetDefinitionsSnapshot();
        object[] playEntries = TaskReadFreePlayEntries(cards);
        timer.Stop();
        if (JsonSerializer.Serialize(before) != JsonSerializer.Serialize(repeated))
            throw new InvalidOperationException("Read-only binding capture changed card state or created bindings.");
        if (!before.All(TaskFreeCardHasNoMechanism))
            throw new InvalidOperationException("Actual root has an unreviewed free/resource mechanism.");
        object[] detectorMethods = detectors.SelectMany(pair => pair.Value.GetInvocationList().Select(callback =>
        {
            MethodInfo method = callback.Method;
            Patches? patches = Harmony.GetPatchInfo(method);
            return (object)new { pair.Key, declaringType = method.DeclaringType!.FullName,
                signature = method.ToString(), method.Module.ModuleVersionId, token = method.MetadataToken,
                ilSha256 = Convert.ToHexString(SHA256.HashData(method.GetMethodBody()!.GetILAsByteArray()!)),
                targetType = callback.Target?.GetType().FullName,
                patchCount = patches is null ? 0 : patches.Prefixes.Count + patches.Postfixes.Count
                    + patches.Transpilers.Count + patches.Finalizers.Count };
        })).ToArray();

        const string id = "combat_solver_free_root_fixture";
        var originalDetector = detectors.FirstOrDefault(pair => pair.Key == id);
        Func<CardPlay, bool> first = _ => false, second = _ => true;
        bool sameNameCountRejected;
        FreePlayBindingRegistry.Register(id, first);
        try
        {
            var firstSnapshot = TaskReadFreeDetectors();
            FreePlayBindingRegistry.Register(id, second);
            var secondSnapshot = TaskReadFreeDetectors();
            sameNameCountRejected = firstSnapshot.Length == secondSnapshot.Length
                && firstSnapshot.Single(pair => pair.Key == id).Value.Method != secondSnapshot.Single(pair => pair.Key == id).Value.Method;
            if (!sameNameCountRejected) throw new InvalidOperationException("Same-name/count detector replacement was not distinguished.");
        }
        finally
        {
            var gate = (System.Threading.Lock)TaskFreeField(typeof(FreePlayBindingRegistry), "Gate").GetValue(null)!;
            using (gate.EnterScope())
            {
                var dictionary = (Dictionary<string, Func<CardPlay, bool>>)TaskFreeField(typeof(FreePlayBindingRegistry),
                    "RegisteredDetectors").GetValue(null)!;
                if (originalDetector.Value is null) dictionary.Remove(id);
                else dictionary[id] = originalDetector.Value;
            }
        }
        var restoredDetectors = TaskReadFreeDetectors();
        if (restoredDetectors.Length != detectors.Length || restoredDetectors.Where((pair, index) =>
            pair.Key != detectors[index].Key || !ReferenceEquals(pair.Value, detectors[index].Value)).Any())
            throw new InvalidOperationException("Original detector references did not restore.");

        var detached = (CardModel)orderedCards[0].MutableClone();
        TaskFreeCard detachedBefore = TaskReadFreeCard(detached, "detached");
        bool clearChanged = FreePlayBindingRegistry.ClearCardFreeThisTurn(detached);
        TaskFreeCard detachedEmpty = TaskReadFreeCard(detached, "detached");
        if (detachedBefore.HasBinding || clearChanged || !detachedEmpty.HasBinding
            || !TaskFreeCardHasNoMechanism(detachedEmpty))
            throw new InvalidOperationException("Native clear did not create a distinguishable empty binding.");
        FreePlayBindingRegistry.MarkCardFreeNextPlay(detached);
        TaskFreeCard detachedMarked = TaskReadFreeCard(detached, "detached");
        if (detachedMarked.Next != 1 || TaskFreeCardHasNoMechanism(detachedMarked))
            throw new InvalidOperationException("Active native free charge was not rejected.");
        if (!FreePlayBindingRegistry.ClearCardFreeAfterPlayed(detached)
            || !TaskFreeCardHasNoMechanism(TaskReadFreeCard(detached, "cleared-charge")))
            throw new InvalidOperationException("Native free charge did not clear before the callback-only test.");

        int costChanges = 0, useChanges = 0;
        SecondaryResourceCostSet costs = detached.SecondaryCosts();
        SecondaryResourcePlayUseSet uses = detached.SecondaryResourceUses();
        costs.Changed += () => costChanges++;
        uses.Changed += () => useChanges++;
        TaskFreeCard callbackOnly = TaskReadFreeCard(detached, "callback-only");
        if (callbackOnly.CostLayers != 0 || callbackOnly.UseLayers != 0
            || callbackOnly.CostCallbacks != 1 || callbackOnly.UseCallbacks != 1
            || callbackOnly.Next != 0 || callbackOnly.ThisTurn != 0 || callbackOnly.RestOfTurn != 0
            || callbackOnly.HasCombatReference || TaskFreeCardHasNoMechanism(callbackOnly))
            throw new InvalidOperationException("Empty container callback was not captured.");
        costs.Set(id, new SecondaryResourceCost(0), SecondaryResourceCostDuration.ThisTurn);
        uses.Require(id, id, 0);
        TaskFreeCard zeroLayer = TaskReadFreeCard(detached, "zero-layer");
        if (costs.HasCosts || uses.HasUses || zeroLayer.CostLayers != 1 || zeroLayer.UseLayers != 1
            || costChanges != 1 || useChanges != 1)
            throw new InvalidOperationException("Zero material layers or their native callbacks were missed.");
        costs.Clear(id); uses.Clear(id);
        if (costChanges != 2 || useChanges != 2)
            throw new InvalidOperationException("Native clear did not invoke attached container callbacks.");
        TaskFreeCard[] after = orderedCards.Select((card, index) => TaskReadFreeCard(card, "root/" + index)).ToArray();
        if (JsonSerializer.Serialize(before) != JsonSerializer.Serialize(after)
            || ParentState() != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Free/resource audit changed its root, parent or live.");
        MethodInfo reader = TaskFreeAttachedStore("CardStates").GetType().GetMethod("TryGetValue")!;
        Patches? readerPatches = Harmony.GetPatchInfo(reader);
        _completedChecks.Add("FreeRoot:PureExistingBindingRead:DeckAllPilesFloatingReturning:RootResourceLayerAndCallbackCapture:DetectorSameNameCountReplacementDistinguishedAndRestored:NativeClearCreatesEmptyBinding:FreeChargeRejected:EmptyContainerCallbacksAndZeroMaterialLayers:FullStampHistoryNineRngParentLive");
        _completedChecks.Add("TASK_FREE_ROOT " + JsonSerializer.Serialize(new { before, detectorMethods,
            definitionCount = definitions.Length, playEntries, sameNameCountRejected,
            detachedBefore, detachedEmpty, detachedMarked, callbackOnly, zeroLayer, costChanges, useChanges,
            captureMilliseconds = timer.Elapsed.TotalMilliseconds,
            reader = new { reader.Module.ModuleVersionId, token = reader.MetadataToken,
                ilSha256 = Convert.ToHexString(SHA256.HashData(reader.GetMethodBody()!.GetILAsByteArray()!)),
                patchCount = readerPatches is null ? 0 : readerPatches.Prefixes.Count + readerPatches.Postfixes.Count
                    + readerPatches.Transpilers.Count + readerPatches.Finalizers.Count },
            rootUnchanged = true, actualPrunes = 0, isWholeOrderCertificate = false, newForkTest = false }));
        return Task.CompletedTask;
    }
}

